<?php
require __DIR__.'/report_api.php';
$date=auditDate(filter_input(INPUT_GET,'date'));$end=clone $date;$end->modify('+1 day');
$loomId=auditLoom(filter_input(INPUT_GET,'loom'));$excluded=auditIds(filter_input(INPUT_GET,'exclude'));
$dataset=auditDataset($db,$date,$end,$loomId?array($loomId):array(),$excluded);
$hourly=array();$total=0.0;$reliable=false;$production=array();$peak=null;$elapsedHours=0;$qualities=array();
for($hour=0;$hour<24;$hour++){$start=clone $date;$start->setTime($hour,0,0);$finish=clone $start;$finish->modify('+1 hour');$report=auditMeasure($dataset,$start,$finish);$s=auditSummary($report);$ids=array();foreach($report['rows'] as $r)if($r['length']!==null&&$r['length']>0){$ids[$r['loomId']]=true;$production[$r['loomId']]=true;}
$future=$start->getTimestamp()>=$dataset['now'];$item=array('hour'=>$hour,'meters'=>$s['length'],'loomCount'=>count($ids),'lengthReliable'=>$s['lengthReliable'],'future'=>$future);$hourly[]=$item;
if(!$future){$reliable=$reliable||$s['lengthReliable'];$total+=$s['length']===null?0:auditRawMeters($report);$elapsedHours+=$report['elapsedSeconds']/3600;if($s['length']!==null&&($peak===null||$s['length']>$peak['meters']))$peak=$item;$qualities[]=$report['quality'];}}
$reliable=$elapsedHours>0&&$reliable;if(!$qualities)$qualities[]=auditMeasure($dataset,$date,$end)['quality'];$quality=auditMergeQuality($qualities);echo json_encode(array('date'=>$date->format('Y-m-d'),'loomId'=>$loomId,'excludedLoomIds'=>$excluded,'hourly'=>$hourly,'summary'=>array('meters'=>$reliable?round($total,2):null,'average'=>$reliable&&$elapsedHours>0?round($total/$elapsedHours,2):null,'loomCount'=>count($production),'peakHour'=>$reliable&&$peak?$peak['hour']:null,'peakMeters'=>$reliable&&$peak?$peak['meters']:null),'quality'=>$quality),JSON_UNESCAPED_UNICODE);